// AcceptanceCodexProductionReachabilityTests.swift 内に追加する提案。
// 同ファイル既存のAX・描画補助関数を利用する。
@Test @MainActor
func expandedGroupKeepsPreviousSummary() throws {
    let app = NSApplication.shared
    app.setActivationPolicy(.prohibited)
    app.finishLaunching()
    let items: [ChatItem] = [
        .commandExecution(id: "a", command: "echo visible", output: "ok", timestamp: .distantPast),
        .commandExecution(id: "b", command: "echo hidden", output: "", timestamp: .distantPast)
    ]
    let host = NSHostingView(rootView: CommandGroupCell(items: items, lastTranscriptID: "b", isTurnRunning: false))
    let window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 720, height: 600), styleMask: [.borderless], backing: .buffered, defer: false)
    window.isReleasedWhenClosed = false
    window.contentView = host
    defer { window.close() }
    window.orderBack(nil)
    settleHeadlessView(host)
    func descendants(_ element: AXUIElement) -> [AXUIElement] {
        [element] + ((axValue(element, kAXChildrenAttribute) as? [AXUIElement]) ?? []).flatMap(descendants)
    }
    let root = AXUIElementCreateApplication(ProcessInfo.processInfo.processIdentifier)
    let windows = try #require(axValue(root, kAXWindowsAttribute) as? [AXUIElement])
    let button = try #require(windows.flatMap(descendants).first {
        axValue($0, kAXValueAttribute) as? String == "折りたたみ中"
    })
    #expect(AXUIElementPerformAction(button, kAXPressAction as CFString) == .success)
    settleHeadlessView(host)
    let text = axElements(in: app).flatMap { [$0.title, $0.value, $0.description].compactMap { $0 } }
    #expect(text.contains { $0.contains("echo hidden") })
}
